'use client';

import { useState } from 'react';
import { Search, Brain, Target, Zap } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export function QuestionSelector({ userRating = 1200 }: { userRating?: number }) {
    const [query, setQuery] = useState("");
    const [results, setResults] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [hasSearched, setHasSearched] = useState(false);

    const handleSearch = async () => {
        if (!query.trim()) return;
        setLoading(true);
        setHasSearched(true);
        setResults([]); // Clear previous results while loading

        try {
            // 1. Call Internal ML API (Node.js Engine)
            const res = await fetch('/api/ml/search', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ query, limit: 50 })
            });
            const data = await res.json();

            if (data.error) throw new Error(data.error);

            // Safe check for results
            const searchResults = data.results || [];

            if (searchResults.length > 0) {
                // 2. Get Predictions for these results
                const predictionRes = await fetch('/api/ml/predict', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        user: { user_rating: userRating, user_id: "me" },
                        problems: searchResults.map((p: any) => ({
                            problem_id: p.problem_id,
                            rating: p.rating || 1200
                        }))
                    })
                });
                const predData = await predictionRes.json();

                // Merge Data
                const merged = searchResults.map((p: any) => {
                    const pred = (predData.predictions || []).find((x: any) => x.problem_id === p.problem_id) || {};
                    return { ...p, ...pred };
                });

                setResults(merged);
            } else {
                setResults([]);
            }

        } catch (error) {
            console.error("ML Service Error", error);
            setResults([]);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="w-full max-w-4xl mx-auto p-6 bg-zinc-900/50 rounded-2xl border border-zinc-800 backdrop-blur-xl">
            <div className="flex items-center gap-3 mb-8">
                <Brain className="text-pink-500" size={32} />
                <div>
                    <h2 className="text-2xl font-bold text-white">Dual-Engine Selector</h2>
                    <p className="text-zinc-400 text-sm">Semantic Search + Win Probability Coach</p>
                </div>
            </div>

            {/* Search Input */}
            <div className="relative mb-8">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500" size={20} />
                <input
                    type="text"
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                    placeholder="Describe a problem... e.g., 'Find shortest path with negative edges'"
                    className="w-full bg-black/40 border border-zinc-700 rounded-xl py-4 pl-12 pr-4 text-white placeholder-zinc-500 focus:outline-none focus:border-pink-500 transition-all font-mono"
                />
                <button
                    onClick={handleSearch}
                    disabled={loading}
                    className="absolute right-2 top-2 bottom-2 bg-pink-600 hover:bg-pink-500 text-white px-6 rounded-lg font-bold transition-all disabled:opacity-50"
                >
                    {loading ? 'Thinking...' : 'Find'}
                </button>
            </div>

            {/* Results List */}
            <div className="space-y-4">
                <AnimatePresence>
                    {results.map((p, i) => {
                        const getProblemUrl = () => {
                            // 1. Codeforces (Standard: 1385C)
                            const cfMatch = p.problem_id.match(/^(\d+)([A-Z]\d?)$/);
                            if (cfMatch) {
                                return `https://codeforces.com/contest/${cfMatch[1]}/problem/${cfMatch[2]}`;
                            }
                            // 2. CSES (Standard: CSES-1633)
                            if (p.problem_id.startsWith('CSES-')) {
                                const id = p.problem_id.split('-')[1];
                                return `https://cses.fi/problemset/task/${id}`;
                            }
                            // 3. Fallback (LeetCode, AtCoder) -> Google Search
                            // "LeetCode Two Sum", "AtCoder Frog 1"
                            const platform = p.problem_id.startsWith('LC') ? 'LeetCode' :
                                p.problem_id.startsWith('ABC') || p.problem_id.startsWith('DP') ? 'AtCoder' : 'Competitive Programming';
                            return `https://www.google.com/search?q=${platform}+${p.title}+problem`;
                        };

                        return (
                            <motion.a
                                key={p.problem_id}
                                href={getProblemUrl()}
                                target="_blank"
                                rel="noopener noreferrer"
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: i * 0.05 }}
                                className="bg-black/20 border border-zinc-800 p-4 rounded-xl flex items-center justify-between group hover:border-pink-500/50 hover:bg-zinc-900/40 transition-all cursor-pointer block"
                            >
                                <div>
                                    <h3 className="text-lg font-bold text-zinc-200 group-hover:text-pink-400 transition-colors flex items-center gap-2">
                                        {p.problem_id}: {p.title || "Unknown Problem"}
                                        <Zap size={14} className="opacity-0 group-hover:opacity-100 transition-opacity text-pink-500" />
                                    </h3>
                                    <div className="flex items-center gap-2 mt-2">
                                        <span className="text-xs font-mono bg-zinc-800 px-2 py-0.5 rounded text-zinc-400">
                                            Rating: {p.rating || "N/A"}
                                        </span>
                                        {p.similarity && (
                                            <span className="text-xs font-mono text-emerald-400">
                                                Match: {Math.round(p.similarity * 100)}%
                                            </span>
                                        )}
                                    </div>
                                </div>

                                {/* Win Probability Bar */}
                                <div className="w-48">
                                    <div className="flex justify-between mb-1">
                                        <span className="text-xs font-bold text-zinc-400 uppercase tracking-wider">
                                            {p.label || "Calculating..."}
                                        </span>
                                        <span className="text-xs font-mono text-zinc-500">{p.win_probability ? Math.round(p.win_probability * 100) : 0}%</span>
                                    </div>
                                    <div className="h-2 w-full bg-zinc-800 rounded-full overflow-hidden">
                                        <div
                                            className={`h-full rounded-full transition-all duration-1000 ${p.win_probability > 0.8 ? 'bg-emerald-500' :
                                                p.win_probability > 0.5 ? 'bg-yellow-500' : 'bg-red-500'
                                                }`}
                                            style={{ width: `${(p.win_probability || 0) * 100}%` }}
                                        ></div>
                                    </div>
                                </div>
                            </motion.a>
                        );
                    })}
                </AnimatePresence>

                {results.length === 0 && !loading && (
                    <div className="text-center py-12 text-zinc-600">
                        <Target className="mx-auto mb-4 opacity-20" size={48} />
                        <p>
                            {hasSearched
                                ? "No problems found similar to that in the database."
                                : "Ask the engine to find something."}
                        </p>
                    </div>
                )}
            </div>
        </div>
    );
}
